<script setup>
import {ref,shallowRef,onBeforeUnmount} from 'vue';import {Button,Field,Cell,Popup,Picker,Uploader} from 'vant';
import 'vant/es/button/style';import 'vant/es/field/style';import 'vant/es/cell/style';import 'vant/es/popup/style';import 'vant/es/picker/style';import 'vant/es/uploader/style';
const props=defineProps({api:Function,question:Object,studentId:[String,Number],active:Function,onChanged:Function}),c=window.GrowingStudentFigureEditor.create(props),m=shallowRef(c.snapshot()),a=c.actions,unsub=c.subscribe(v=>m.value=v),pageOpen=ref(false),frame=ref();let start=null;
c.actions.load();onBeforeUnmount(()=>{unsub();c.destroy();});
function point(e){const r=frame.value.getBoundingClientRect();return{x:Math.min(1,Math.max(0,(e.clientX-r.left)/r.width)),y:Math.min(1,Math.max(0,(e.clientY-r.top)/r.height))};}
function down(e){if(m.value.busy)return;e.preventDefault();start=point(e);frame.value.setPointerCapture(e.pointerId);}
function move(e){if(!start)return;const p=point(e);a.select({x:Math.min(p.x,start.x),y:Math.min(p.y,start.y),width:Math.abs(p.x-start.x),height:Math.abs(p.y-start.y)});}
function coordinate(key,value){a.select({...m.value.selected,x:m.value.selected?.x||0,y:m.value.selected?.y||0,width:m.value.selected?.width??1,height:m.value.selected?.height??1,[key]:Number(value)/100});}
function upload(item,source){a.upload(item.file,source);}
const coordinates=[['x','左边距'],['y','上边距'],['width','宽'],['height','高']];
</script>
<template><section class="student-figure-editor"><p>在原稿上框选图形，包含点名和全部标注；多图或跨页可多次添加。</p><p v-if="!m.loaded" role="status">{{m.busy?'正在读取题图…':'题图尚未加载。'}}</p><Button v-if="!m.loaded&&!m.busy" @click="a.load">重试读取</Button><template v-if="m.loaded"><Cell title="来源页" :value="'第 '+m.page+' 页'" is-link :clickable="!m.busy" @click="!m.busy&&(pageOpen=true)"/><template v-if="m.source"><div ref="frame" class="figure-selector" @pointerdown="down" @pointermove="move" @pointerup="start=null" @pointercancel="start=null"><img :src="m.source.image" :alt="'第 '+m.page+' 页，框选题图'" draggable="false"/><span v-if="m.selected" :style="{left:m.selected.x*100+'%',top:m.selected.y*100+'%',width:m.selected.width*100+'%',height:m.selected.height*100+'%'}"/></div><div class="figure-coordinates"><Field v-for="[key,label] in coordinates" :key="key" :model-value="String((m.selected?.[key]??(key==='width'||key==='height'?1:0))*100)" :label="label+' %'" type="number" :disabled="m.busy" @update:model-value="v=>coordinate(key,v)"/></div><div class="figure-actions"><Button :disabled="m.busy" @click="a.add">添加选框</Button><Button :disabled="m.busy" @click="a.reset">清空选框</Button><Button type="primary" :disabled="m.busy" :loading="m.busy" @click="a.save">保存题图选框</Button></div></template><template v-else><p class="warning">该页没有保存原图，请补回这一页的原照片。</p><Uploader accept="image/jpeg,image/png,image/webp" :disabled="m.busy" :after-read="item=>upload(item,true)"><Button :disabled="m.busy">补回本页原稿</Button></Uploader></template><ol><li v-for="(region,i) in m.regions" :key="i">题图 {{i+1}} · 第 {{region.page}} 页 <Button icon="cross" :aria-label="'移除题图选框 '+(i+1)" :disabled="m.busy" @click="a.remove(i)"/></li></ol><Uploader accept="image/jpeg,image/png,image/webp" :disabled="m.busy" :after-read="item=>upload(item,false)"><Button :disabled="m.busy">补传本题图形</Button></Uploader><div v-if="!['english','physics'].includes(question.subject||m.paper.subject)" class="figure-actions"><Button :disabled="m.busy" @click="a.generate">{{m.attachment?.drawing?'重新绘制题图':'生成题图'}}</Button><Button v-if="m.attachment?.drawing&&m.attachment.drawingRevision===question.revision&&!m.attachment.drawingReviewed" :disabled="m.busy" @click="a.confirm">已核对，图形正确</Button></div></template><p role="status" aria-live="polite">{{m.status}}</p><Popup v-model:show="pageOpen" position="bottom" round><header><h3>来源页</h3><Button icon="cross" aria-label="关闭来源页选择" @click="pageOpen=false"/></header><Picker :columns="(question.pages||[]).map(n=>({text:'第 '+n+' 页',value:n}))" :model-value="[m.page]" @confirm="({selectedValues})=>{a.page(selectedValues[0]);pageOpen=false}"><template #cancel><Button icon="cross" aria-label="关闭来源页选择" @click="pageOpen=false"/></template></Picker></Popup></section></template>
<style scoped>.student-figure-editor{min-width:0;line-height:1.8}.figure-selector{position:relative;touch-action:none;line-height:0;user-select:none}.figure-selector img{width:100%;height:auto;display:block}.figure-selector span{position:absolute;border:2px solid #b42318;background:#b4231818;pointer-events:none}.figure-coordinates{display:grid;grid-template-columns:1fr 1fr}.figure-actions,header{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:14px 0}header{justify-content:space-between}.student-figure-editor.student-figure-editor :deep(.van-button){min-height:44px}.student-figure-editor li .van-button,header .van-button{width:44px;padding:0}.warning{color:#b42318}</style>

<style scoped>
/* visual-restore-legacy */
.student-figure-editor{font:15px/1.65 "Segoe UI","Microsoft YaHei",system-ui,sans-serif;color:#25332c}.student-figure-editor h2{font-size:20px;font-weight:600}.student-figure-editor header{margin:0 0 16px}.student-figure-editor.student-figure-editor :deep(.van-button){height:auto;min-height:44px;padding:8px 14px;border:1px solid #b8c5bc;border-radius:8px;background:#fff;color:#25332c;font:14px/1.5 "Segoe UI","Microsoft YaHei",system-ui,sans-serif}.student-figure-editor.student-figure-editor :deep(.van-button--primary){background:#25332c;color:#fff;border-color:#25332c}.student-figure-editor.student-figure-editor :deep(.van-field){display:block;background:transparent;padding:0;margin:12px 0}.student-figure-editor.student-figure-editor :deep(.van-field__label){width:auto;margin-bottom:6px}.student-figure-editor.student-figure-editor :deep(.van-field__control){min-height:40px;padding:10px 12px;border:1px solid #b8c5bc;border-radius:8px;background:#fff;font:inherit}.figure-selector{border:1px solid #e0e6e1;border-radius:8px;overflow:hidden}.figure-actions{gap:10px}.figure-coordinates{gap:12px}.student-figure-editor header :deep(.van-button){width:44px;padding:0}
</style>
